<?php
/** Download only reviewed source files; never runtime settings, credentials or customer data. */
class ConnectionDownloads {
    public static function zip($files){$body='';$directory='';$count=0;foreach($files as $name=>$data){$size=strlen($data);$crc=crc32($data);$offset=strlen($body);$length=strlen($name);$body.=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,33,$crc,$size,$size,$length,0).$name.$data;$directory.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,33,$crc,$size,$size,$length,0,0,0,0,0,$offset).$name;$count++;}return $body.$directory.pack('VvvvvVVv',0x06054b50,0,0,$count,$count,strlen($directory),strlen($body),0);}
    public static function package($project,$kind){
        $root=dirname(__DIR__,2);$files=[];
        if($kind==='chatgpt'){AiAccess::need('ai_connect');$files['maarksho-chatgpt/instructions.fa.md']=file_get_contents($root.'/integrations/chatgpt/instructions.fa.md');$files['maarksho-chatgpt/openapi.json']=json_encode(AiSchema::openapi(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$files['maarksho-chatgpt/connection.json']=json_encode(['project'=>$project['id'],'mcp'=>AiOAuth::base().'/panel/ai_mcp.php','authorization'=>AiOAuth::base().'/panel/ai_oauth.php?action=authorize','token'=>AiOAuth::base().'/panel/ai_oauth.php?action=token','setup'=>AiOAuth::base().'/panel/ai-connect.php?project='.rawurlencode($project['id']),'note'=>'ثبت اپ، آدرس بازگشت و تأیید OAuth توسط مالک لازم است؛ این بسته هیچ کلید یا توکنی ندارد.'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$files['maarksho-chatgpt/README.fa.md']="# اتصال ChatGPT مارک‌شو\nاین بسته افزونهٔ وردپرس نیست. برای MCP، آدرس mcp در connection.json را در اپ سفارشی حساب ChatGPT وارد کنید. Callback ارائه‌شدهٔ ChatGPT را در صفحهٔ اتصال پنل ثبت کنید؛ نوع عمومی از PKCE استفاده می‌کند. برای GPT Actions فایل openapi.json و OAuth را تنظیم کنید. دسترسی اپ سفارشی به امکانات حساب ChatGPT وابسته است.\nابتدا project_context و project_connections را فراخوانی کنید و نام پروژه را بررسی کنید. برای نوشتن سایت website.write را جدا تأیید کنید. هیچ توکنی داخل این ZIP نیست؛ پس از لغو OAuth، اتصال قبلی مجاز نیست. کلید API گزارش‌های خودکار مستقل از اشتراک ChatGPT است.\n";}
        elseif($kind==='python'){AiAccess::need('extract');foreach(['app.py','requirements.txt','README-fa.md','crawler/__init__.py','crawler/scraper.py','tiam-agent/launcher.py','tiam-agent/clipboard_input.py','tiam-agent/README-fa.md'] as $name){$file=$root.'/app/'.$name;if(!is_file($file)||is_link($file))throw new RuntimeException('بستهٔ پایتون کامل نیست.');$files['maarksho-tools/app/'.$name]=file_get_contents($file);}foreach(['tiam_inventory_agent.py','tiam_agent.py','tiam_sql_diagnostic.ps1'] as $name){$files['maarksho-tools/panel/'.$name]=file_get_contents($root.'/panel/'.$name);}$files['maarksho-tools/requirements-agent.txt']="pyodbc==5.2.0\n";$files['maarksho-tools/PROJECT.fa.md']="# ابزارهای پروژه\nپروژه: ".$project['id']."\nاین بسته سورس پایتون است، نه فایل اجرایی ویندوز. پیش‌نیازها و روش اجرای هر ابزار در README آن است. کلید، تنظیمات مشتری و دادهٔ محصولات در بسته نیست. خروجی را در همان پروژه پیش‌نمایش و تأیید کنید. ابزار استخراج سایت و ابزار ورودی تیام دو کاربرد جدا دارند.\n";}
        else throw new RuntimeException('بستهٔ دانلود معتبر نیست.');
        foreach($files as $value)if(!is_string($value))throw new RuntimeException('فایل بسته در دسترس نیست.');$hashes=[];foreach($files as $name=>$data)$hashes[$name]=hash('sha256',$data);$files['manifest.json']=json_encode(['package'=>$kind,'version'=>'1.1.0','sha256'=>$hashes],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);return self::zip($files);
    }
}
